CREATE TABLE public.friendships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL REFERENCES public.profiles(id),receiver_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','blocked')),created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>receiver_id)); CREATE UNIQUE INDEX friendship_pair ON public.friendships(least(sender_id,receiver_id),greatest(sender_id,receiver_id)); GRANT SELECT ON public.friendships TO authenticated; GRANT ALL ON public.friendships TO service_role; ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY; CREATE POLICY friendship_read ON public.friendships FOR SELECT TO authenticated USING(auth.uid() IN (sender_id,receiver_id));
CREATE FUNCTION public.fanmap_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.friendships WHERE status='accepted' AND least(sender_id,receiver_id)=least(a,b) AND greatest(sender_id,receiver_id)=greatest(a,b)) $$;
CREATE TABLE public.friend_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),friendship_id uuid NOT NULL REFERENCES public.friendships(id),sender_id uuid NOT NULL REFERENCES public.profiles(id),text text NOT NULL CHECK(length(text) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz); GRANT SELECT,INSERT ON public.friend_messages TO authenticated; GRANT ALL ON public.friend_messages TO service_role; ALTER TABLE public.friend_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY friend_message_read ON public.friend_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.friendships WHERE id=friendship_id AND status='accepted' AND auth.uid() IN(sender_id,receiver_id))); CREATE POLICY friend_message_write ON public.friend_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.fanmap_verified() AND EXISTS(SELECT 1 FROM public.friendships WHERE id=friendship_id AND status='accepted' AND auth.uid() IN(sender_id,receiver_id)));
CREATE TABLE public.connection_tokens(token uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes'); GRANT SELECT ON public.connection_tokens TO authenticated; GRANT ALL ON public.connection_tokens TO service_role; ALTER TABLE public.connection_tokens ENABLE ROW LEVEL SECURITY; CREATE POLICY token_self ON public.connection_tokens FOR SELECT TO authenticated USING(user_id=auth.uid() AND expires_at>now());
CREATE TABLE public.guide_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),event_id text NOT NULL REFERENCES public.events(id),messages jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id)); GRANT SELECT,INSERT,UPDATE ON public.guide_threads TO authenticated; GRANT ALL ON public.guide_threads TO service_role; ALTER TABLE public.guide_threads ENABLE ROW LEVEL SECURITY; CREATE POLICY guide_self ON public.guide_threads TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.location_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL REFERENCES public.profiles(id),receiver_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','declined','stopped')),activated_at timestamptz,expires_at timestamptz,sender_consent boolean NOT NULL DEFAULT true,receiver_consent boolean NOT NULL DEFAULT false,meeting_lat double precision,meeting_lng double precision,meeting_proposer uuid,meeting_accepted boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(sender_id<>receiver_id)); GRANT SELECT ON public.location_sessions TO authenticated; GRANT ALL ON public.location_sessions TO service_role; ALTER TABLE public.location_sessions ENABLE ROW LEVEL SECURITY; CREATE POLICY location_session_read ON public.location_sessions FOR SELECT TO authenticated USING(auth.uid() IN(sender_id,receiver_id) AND public.fanmap_verified() AND public.fanmap_friends(sender_id,receiver_id));
CREATE TABLE public.location_positions(session_id uuid NOT NULL REFERENCES public.location_sessions(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id),lat double precision NOT NULL CHECK(lat BETWEEN -90 AND 90),lng double precision NOT NULL CHECK(lng BETWEEN -180 AND 180),accuracy double precision NOT NULL CHECK(accuracy>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(session_id,user_id)); GRANT SELECT ON public.location_positions TO authenticated; GRANT ALL ON public.location_positions TO service_role; ALTER TABLE public.location_positions ENABLE ROW LEVEL SECURITY; CREATE POLICY positions_live_read ON public.location_positions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.location_sessions s WHERE s.id=session_id AND s.status='active' AND s.expires_at>now() AND auth.uid() IN(s.sender_id,s.receiver_id) AND public.fanmap_verified() AND public.fanmap_friends(s.sender_id,s.receiver_id)));
CREATE FUNCTION public.fanmap_location_transition(s uuid, action text, reverified boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.location_sessions; BEGIN SELECT * INTO x FROM public.location_sessions WHERE id=s FOR UPDATE; IF auth.uid() IS NULL OR NOT auth.uid() IN(x.sender_id,x.receiver_id) OR NOT public.fanmap_verified() OR NOT public.fanmap_friends(x.sender_id,x.receiver_id) THEN RAISE EXCEPTION 'Location permission denied'; END IF; IF action='stop' OR action='decline' THEN UPDATE public.location_sessions SET status=CASE WHEN action='stop' THEN 'stopped' ELSE 'declined' END WHERE id=s; DELETE FROM public.location_positions WHERE session_id=s; ELSIF action='accept' THEN IF auth.uid()<>x.receiver_id OR x.status<>'pending' THEN RAISE EXCEPTION 'This request cannot be accepted'; END IF; UPDATE public.location_sessions SET status='active',activated_at=now(),expires_at=now()+interval '30 minutes' WHERE id=s; ELSE RAISE EXCEPTION 'Invalid location action'; END IF; END $$;
REVOKE ALL ON FUNCTION public.fanmap_location_transition(uuid,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.fanmap_location_transition(uuid,text,boolean) TO authenticated;
CREATE POLICY media_owner_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='fanmap-media' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY media_owner_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='fanmap-media' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY media_authorized_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='fanmap-media' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.reels WHERE path=name AND status='approved' AND public.fanmap_eligible(event_id)) OR EXISTS(SELECT 1 FROM public.deliveries WHERE media_path=name AND recipient_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.reels JOIN public.events ON events.id=reels.event_id WHERE path=name AND public.fanmap_artist(events.artist_id))));
ALTER PUBLICATION supabase_realtime ADD TABLE public.friend_messages,public.friendships,public.deliveries;